.boundarysim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2438;
    background: linear-gradient(160deg, #f6f1ec 0%, #efe7f0 100%);
    border-radius: 18px;
}

.boundarysim-container * {
    box-sizing: border-box;
}

.boundarysim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #3b2f5c 0%, #6b4a86 55%, #b5638a 100%);
    color: #fbf4f7;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(59, 47, 92, 0.32);
}

.boundarysim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.boundarysim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f4d9bf;
    background: rgba(255, 255, 255, 0.13);
    padding: 5px 14px;
    border-radius: 999px;
}

.boundarysim-subtitle {
    margin: 14px auto 0;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #f1e4ee;
}

.boundarysim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4a3d63;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.boundarysim-period-counter #currentDay,
.boundarysim-period-counter #maxPeriods {
    font-weight: 800;
    color: #3b2f5c;
}

.boundarysim-round-name {
    background: #e7dcf0;
    color: #5a3d7a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.boundarysim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a8431f;
    background: #fbe4d8;
    padding: 4px 12px;
    border-radius: 999px;
}

.boundarysim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.boundarysim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e7ddec;
    box-shadow: 0 4px 14px rgba(59, 47, 92, 0.06);
    border-top: 4px solid #6b4a86;
}

.boundarysim-card-wellbeing { border-top-color: #2f8f7a; }
.boundarysim-card-performance { border-top-color: #2f6fb0; }
.boundarysim-card-credibility { border-top-color: #c98a16; }
.boundarysim-card-team { border-top-color: #9b4d9b; }

.boundarysim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a6b8c;
}

.boundarysim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #3b2f5c;
}

.boundarysim-card-wellbeing .boundarysim-value { color: #2f8f7a; }
.boundarysim-card-performance .boundarysim-value { color: #2f6fb0; }
.boundarysim-card-credibility .boundarysim-value { color: #c98a16; }
.boundarysim-card-team .boundarysim-value { color: #9b4d9b; }

.boundarysim-sublabel {
    font-size: 0.76rem;
    color: #8a7c98;
    line-height: 1.35;
}

.boundarysim-wellbeing-burnout .boundarysim-value { color: #c0392b; }
.boundarysim-wellbeing-healthy .boundarysim-value { color: #2f8f7a; }

.boundarysim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #3b2f5c;
    color: #f3ebf3;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.boundarysim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.boundarysim-budget-gap-open #budgetDisplay { color: #ffb59c; }
.boundarysim-budget-gap-closed #budgetDisplay { color: #a8e6c9; }

.boundarysim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #b5638a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(59, 47, 92, 0.05);
}

.boundarysim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.boundarysim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #3b2f5c;
    margin-bottom: 6px;
}

.boundarysim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #463a59;
}

.boundarysim-briefing-text strong { color: #2f8f7a; }
.boundarysim-briefing-text em { color: #a8431f; font-style: italic; }

.boundarysim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e7ddec;
    box-shadow: 0 4px 14px rgba(59, 47, 92, 0.06);
}

.boundarysim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #3b2f5c;
    border-bottom: 2px solid #efe5f1;
    padding-bottom: 8px;
}

.boundarysim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3d3252;
    margin: 14px 0 6px;
}

.boundarysim-container select,
.boundarysim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d3c4dd;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf6fb;
    color: #2b2438;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.boundarysim-container select:focus,
.boundarysim-container input[type="number"]:focus {
    outline: none;
    border-color: #b5638a;
    box-shadow: 0 0 0 3px rgba(181, 99, 138, 0.16);
}

.boundarysim-container select option {
    background-color: #ffffff;
    color: #2b2438;
}

.boundarysim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b5638a;
}

.boundarysim-range-readout,
.boundarysim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b4a86;
    margin-top: 4px;
}

.boundarysim-range-readout span:last-child,
.boundarysim-alloc-readout span:nth-child(2) {
    color: #2f8f7a;
    font-weight: 800;
}

.boundarysim-hint {
    font-size: 0.8rem;
    color: #8a7c98;
    margin-top: 4px;
    line-height: 1.4;
}

.boundarysim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.boundarysim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f1f9;
    border: 1px solid #e6dbec;
    border-radius: 9px;
    padding: 8px 12px;
}

.boundarysim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #3d3252;
}

.boundarysim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.boundarysim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.boundarysim-container .btn-primary {
    background: linear-gradient(135deg, #2f8f7a 0%, #6b4a86 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(47, 143, 122, 0.26);
}

.boundarysim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.boundarysim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d3c4dd;
    color: #7a6b8c;
}

.boundarysim-coach {
    background: #3b2f5c;
    color: #f1e9f3;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(59, 47, 92, 0.24);
}

.boundarysim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #d3a8e0;
    margin-bottom: 8px;
}

.boundarysim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.boundarysim-coach-body strong { color: #8fe6cf; }
.boundarysim-coach-body em { color: #ffc2a8; font-style: italic; }

.boundarysim-history,
.boundarysim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e7ddec;
    box-shadow: 0 4px 14px rgba(59, 47, 92, 0.06);
}

.boundarysim-history h3,
.boundarysim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #3b2f5c;
}

.boundarysim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3d3252;
}

.boundarysim-container table#usfHistoryTable th {
    background: #f1e9f3;
    color: #3b2f5c;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2d4ea;
}

.boundarysim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f1eaf4;
}

.boundarysim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf6fb;
}

.boundarysim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .boundarysim-container {
        padding: 14px;
    }
    .boundarysim-header h1 {
        font-size: 1.7rem;
    }
    .boundarysim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .boundarysim-value {
        font-size: 2rem;
    }
    .boundarysim-clock {
        margin-left: 0;
    }
    .boundarysim-period-counter {
        font-size: 0.88rem;
    }
    .boundarysim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .boundarysim-alloc-row {
        flex-wrap: wrap;
    }
    .boundarysim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .boundarysim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, self-contained) ===== */
.boundarysim-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #10242a; text-align: center; padding: 4px 2px 8px; }
.boundarysim-cm-title { font-size: 20px; font-weight: 700; color: #14565e; margin-bottom: 14px; }
.boundarysim-cm-scorewrap { background: linear-gradient(135deg, #14565e 0%, #2f9ba0 55%, #5fc8bf 100%); color: #eefcfa; border-radius: 14px; padding: 18px 16px; margin: 0 auto 16px; max-width: 420px; }
.boundarysim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; }
.boundarysim-cm-score-max { font-size: 20px; font-weight: 600; opacity: 0.85; }
.boundarysim-cm-grade { font-size: 18px; font-weight: 700; margin-top: 8px; }
.boundarysim-cm-badges { margin-top: 10px; }
.boundarysim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; padding: 4px 12px; border-radius: 999px; }
.boundarysim-cm-badge-ok { background: #cceceb; color: #14565e; }
.boundarysim-cm-badge-miss { background: #f7e2cf; color: #9a5a16; }
.boundarysim-cm-kpis { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin: 0 auto 14px; max-width: 500px; }
.boundarysim-cm-kpi { flex: 1 1 105px; min-width: 105px; background: #eaf6f5; border: 1px solid #cceceb; border-radius: 10px; padding: 10px 6px; }
.boundarysim-cm-kpi-val { font-size: 20px; font-weight: 700; color: #1c6b6f; }
.boundarysim-cm-kpi-lbl { font-size: 11px; font-weight: 600; color: #4a6266; text-transform: uppercase; letter-spacing: .3px; margin-top: 2px; }
.boundarysim-cm-insights { text-align: left; max-width: 520px; margin: 0 auto; background: #f2faf9; border-left: 4px solid #2f9ba0; border-radius: 8px; padding: 12px 16px; }
.boundarysim-cm-ins-h { font-weight: 700; color: #14565e; margin-bottom: 6px; font-size: 14px; }
.boundarysim-cm-insights ul { margin: 0; padding-left: 18px; }
.boundarysim-cm-insights li { font-size: 13px; line-height: 1.5; margin-bottom: 6px; color: #22383c; }
@media (max-width: 480px) { .boundarysim-cm-kpi { flex-basis: 40%; } .boundarysim-cm-score { font-size: 38px; } .boundarysim-cm-scorewrap { max-width: 100%; } }

