(function() {
    'use strict';

    class BoundaryAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Boundary Work`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_WELLBEING = 22;     // <6h sleep, +40% exhaustion band
            this.START_PERFORMANCE = 50;   // delivering, but on borrowed energy
            this.START_CREDIBILITY = 15;   // no boundary norms exist yet
            this.START_TEAM = 25;          // the 7 reports mirror an always-on lead
            this.GAP_HOURS = 20;           // ~70h demand vs ~50h sustainable capacity
            this.WELLBEING_FLOOR = 45;     // below this = sustained burnout / quit-risk band
            this.WIN_WELLBEING = 60;       // sustainable
            this.WIN_PERFORMANCE = 60;     // sprint delivered & standing held

            // Concept-correct answers (the textbook play).
            this.TRUE_FRAME = `identity`;
            this.TRUE_STYLE = `integration`;
            this.TRUE_THREAT = `star`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    wellbeing: this.START_WELLBEING,
                    performance: this.START_PERFORMANCE,
                    credibility: this.START_CREDIBILITY,
                    team: this.START_TEAM,
                    gapOpen: this.GAP_HOURS,
                    burnoutEnding: false,
                    clientFail: false,
                    wellbeingHistory: [this.START_WELLBEING],
                    performanceHistory: [this.START_PERFORMANCE],
                    teamHistory: [this.START_TEAM],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a MIDDLING / neutral mix — never the textbook play.
                state.decisions = {
                    frame: `time`,
                    style: `hardseg`,
                    threat: `none`,
                    honesty: 50,
                    delegate: 3,
                    temporal: 5,
                    physical: 4,
                    comm: 8,
                    cadence: `realtime`,
                    enforce: 50,
                    reframe: `keep`,
                    boss: `accept`,
                    partner: `promise`,
                    nonneg: `none`,
                    escalation: `cave`,
                    exception: `always`,
                    norm: `solo`,
                    indicators: `lagonly`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const fr = document.getElementById(`frameInput`);
                const st = document.getElementById(`styleInput`);
                const th = document.getElementById(`threatInput`);
                const hon = document.getElementById(`honestyInput`);
                if (fr) decisions.frame = fr.value;
                if (st) decisions.style = st.value;
                if (th) decisions.threat = th.value;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const del = document.getElementById(`delegateInput`);
                const tmp = document.getElementById(`temporalInput`);
                const phy = document.getElementById(`physicalInput`);
                const cm = document.getElementById(`commInput`);
                if (del) decisions.delegate = parseFloat(del.value);
                if (tmp) decisions.temporal = parseFloat(tmp.value);
                if (phy) decisions.physical = parseFloat(phy.value);
                if (cm) decisions.comm = parseFloat(cm.value);
                const parts = [decisions.delegate, decisions.temporal, decisions.physical, decisions.comm];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.delegate + decisions.temporal + decisions.physical + decisions.comm) * 10) / 10;
                if (Math.abs(total - this.GAP_HOURS) > 0.05) {
                    warn(`warn_alloc_total`); return false;
                }
                const cad = document.getElementById(`cadenceInput`);
                const enf = document.getElementById(`enforceInput`);
                if (cad) decisions.cadence = cad.value;
                if (enf) decisions.enforce = parseInt(enf.value, 10);
                if (!Number.isFinite(decisions.enforce) || decisions.enforce < 0 || decisions.enforce > 100) {
                    warn(`warn_enforce_range`); return false;
                }
            } else if (round === 3) {
                const re = document.getElementById(`reframeInput`);
                const bo = document.getElementById(`bossInput`);
                const pa = document.getElementById(`partnerInput`);
                const nn = document.getElementById(`nonnegInput`);
                if (re) decisions.reframe = re.value;
                if (bo) decisions.boss = bo.value;
                if (pa) decisions.partner = pa.value;
                if (nn) decisions.nonneg = nn.value;
            } else if (round === 4) {
                const es = document.getElementById(`escalationInput`);
                const ex = document.getElementById(`exceptionInput`);
                const nm = document.getElementById(`normInput`);
                const ind = document.getElementById(`indicatorsInput`);
                const cv = document.getElementById(`convictionInput`);
                if (es) decisions.escalation = es.value;
                if (ex) decisions.exception = ex.value;
                if (nm) decisions.norm = nm.value;
                if (ind) decisions.indicators = ind.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // wbDelta = well-being; perfDelta = sprint delivery & standing;
            // credDelta = whether her boundaries actually hold; teamDelta = the 7-report norm.
            let wbDelta = 0, perfDelta = 0, credDelta = 0, teamDelta = 0;
            let gapClosed = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: identity-and-boundary, not time-management (Common Error 1).
                if (d.frame === this.TRUE_FRAME) {
                    wbDelta += 8; credDelta += 10; coachKey = `coach_r1_identity`;
                } else if (d.frame === `time`) {
                    wbDelta -= 4; credDelta -= 6; coachKey = `coach_r1_time`;
                } else if (d.frame === `effort`) {
                    wbDelta -= 10; credDelta -= 4; coachKey = `coach_r1_effort`;
                } else { // client
                    perfDelta -= 6; credDelta -= 4; coachKey = `coach_r1_client`;
                }

                // Person-fit: Priya's real preference is mild integration (Decision Tree #6).
                if (d.style === this.TRUE_STYLE) {
                    credDelta += 10; wbDelta += 4;
                    if (d.frame === this.TRUE_FRAME) coachKey = `coach_r1_diag_sharp`;
                } else if (d.style === `hardseg`) {
                    credDelta -= 8; coachKey = `coach_r1_hardseg`;
                } else { // ignore
                    credDelta -= 6; wbDelta -= 2;
                }

                // Naming the threatened identity ("the always-available star").
                if (d.threat === this.TRUE_THREAT) {
                    credDelta += 8; teamDelta += 2;
                } else if (d.threat === `skills`) {
                    wbDelta -= 4; coachKey = `coach_r1_skills`;
                } else { // none
                    credDelta -= 6; coachKey = `coach_r1_nothreat`;
                }

                // Honesty: willingness to face the identity, not just the calendar.
                if (d.honesty >= 60) { credDelta += 6; wbDelta += 3; }
                else if (d.honesty <= 25) { credDelta -= 6; coachKey = `coach_r1_lowhonesty`; }

                summaryKey = (d.frame === this.TRUE_FRAME && d.style === this.TRUE_STYLE && d.threat === this.TRUE_THREAT) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Boundary-work tactics across families + close the 20h gap (Common Error 2).
                const del = d.delegate, tmp = d.temporal, phy = d.physical, cm = d.comm;
                gapClosed = del + tmp + phy + cm;

                // Coherent plan spans at least three families with real weight, led by
                // communicative (renegotiation) and behavioural (delegation), not a grab-bag.
                const families = [del, tmp, phy, cm];
                const familiesUsed = families.filter((v) => v >= 2).length;
                const commLed = cm >= 5;
                const delegates = del >= 3;

                if (familiesUsed >= 3 && commLed && delegates) {
                    wbDelta += 12; credDelta += 8; perfDelta += 4; coachKey = `coach_r2_coherent`;
                } else if (familiesUsed >= 3) {
                    wbDelta += 7; credDelta += 4; coachKey = `coach_r2_spread`;
                } else if (familiesUsed <= 1) {
                    wbDelta -= 6; credDelta -= 6; coachKey = `coach_r2_grabbag`;
                } else {
                    wbDelta += 2;
                }
                // Under-delegation is a primary driver of the gap (Common Error / DelegationRescue link).
                if (del < 2) { perfDelta -= 6; wbDelta -= 4; coachKey = `coach_r2_nodelegate`; }
                // Pure physical/temporal walls with no renegotiation just shifts demand, not closes it.
                if (cm < 2) { credDelta -= 6; perfDelta -= 4; coachKey = `coach_r2_nocomm`; }

                // Reset the client cadence explicitly.
                switch (d.cadence) {
                    case `workable`: perfDelta += 10; credDelta += 8; coachKey = (commLed ? `coach_r2_workable` : coachKey); break;
                    case `realtime`: wbDelta -= 10; credDelta -= 6; coachKey = `coach_r2_realtime`; break;
                    case `silent`: credDelta -= 12; perfDelta -= 6; coachKey = `coach_r2_silent`; break;
                }

                // Enforcement: announced-but-unenforced limits backfire (Common Error 2).
                if (d.enforce >= 60) { credDelta += 10; wbDelta += 4; }
                else if (d.enforce <= 30) { credDelta -= 12; wbDelta -= 2; coachKey = `coach_r2_unenforced`; }
                else { credDelta += 2; }

                summaryKey = (familiesUsed >= 3 && commLed && delegates && d.cadence === `workable` && d.enforce >= 60) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Identity work + respond to the threat (Common Errors 1 & 3).
                switch (d.reframe) {
                    case `judgement`: credDelta += 12; wbDelta += 10; teamDelta += 4; coachKey = `coach_r3_judgement`; break;
                    case `keep`: wbDelta -= 12; credDelta -= 8; coachKey = `coach_r3_keep`; break;
                    case `withdraw`: perfDelta -= 12; teamDelta -= 4; coachKey = `coach_r3_withdraw`; break;
                }

                // Skip-level boss: reframe warmly, not blunt rejection (Common Error 3).
                switch (d.boss) {
                    case `reframe`: perfDelta += 8; credDelta += 8; coachKey = (d.reframe === `judgement` ? `coach_r3_bossreframe` : coachKey); break;
                    case `blunt`: perfDelta -= 10; credDelta -= 2; coachKey = `coach_r3_blunt`; break;
                    case `accept`: wbDelta -= 8; credDelta -= 8; coachKey = `coach_r3_bossaccept`; break;
                }

                // The partner conversation — protect the relationship and the home load.
                switch (d.partner) {
                    case `share`: wbDelta += 12; teamDelta += 2; break;
                    case `promise`: wbDelta -= 6; coachKey = `coach_r3_promise`; break;
                    case `avoid`: wbDelta -= 10; coachKey = `coach_r3_avoid`; break;
                }

                // The single non-negotiable — credible only if it is realistic and held.
                switch (d.nonneg) {
                    case `bedtime`: credDelta += 10; wbDelta += 6; break;
                    case `none`: credDelta -= 8; coachKey = `coach_r3_nononneg`; break;
                    case `weekend`: credDelta -= 6; coachKey = `coach_r3_overpromise`; break;
                }

                summaryKey = (d.reframe === `judgement` && d.boss === `reframe` && d.partner === `share`) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Sustain through the sprint, bounded flexibility, reset the team norm.
                // The 9pm escalation tests whether the stated boundary actually holds.
                switch (d.escalation) {
                    case `cadence`: credDelta += 12; wbDelta += 8; perfDelta += 6; coachKey = `coach_r4_cadence`; break;
                    case `cave`: wbDelta -= 12; credDelta -= 10; coachKey = `coach_r4_cave`; break;
                    case `ignore`: perfDelta -= 14; teamDelta -= 2; ds.clientFail = true; coachKey = `coach_r4_ignore`; break;
                }

                // Bounded exception vs uncontrolled erosion (Permeability & Flexibility).
                switch (d.exception) {
                    case `bounded`: perfDelta += 10; credDelta += 8; wbDelta += 2; coachKey = (d.escalation === `cadence` ? `coach_r4_bounded` : coachKey); break;
                    case `never`: perfDelta -= 12; coachKey = `coach_r4_never`; break;
                    case `always`: credDelta -= 12; wbDelta -= 6; coachKey = `coach_r4_alwaysflex`; break;
                }

                // The team multiplier — convert her boundary into a norm for the seven reports.
                switch (d.norm) {
                    case `asyncpool`: teamDelta += 22; wbDelta += 4; credDelta += 4; break;
                    case `solo`: teamDelta -= 10; coachKey = `coach_r4_solo`; break;
                    case `tellthem`: teamDelta -= 16; credDelta -= 6; coachKey = `coach_r4_tellthem`; break;
                }

                // Leading + lagging indicators to know it is working.
                switch (d.indicators) {
                    case `leadlag`: wbDelta += 6; teamDelta += 6; coachKey = (d.norm === `asyncpool` ? `coach_r4_leadlag` : coachKey); break;
                    case `lagonly`: wbDelta -= 2; break;
                    case `none`: wbDelta -= 6; teamDelta -= 4; coachKey = `coach_r4_noindicators`; break;
                }

                // Conviction nudges well-being and credibility.
                const convAdj = Math.round((d.conviction - 60) / 8);
                wbDelta += convAdj; credDelta += convAdj;

                summaryKey = (d.escalation === `cadence` && d.exception === `bounded` && d.norm === `asyncpool` && d.indicators === `leadlag`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Close the demand-capacity gap (Round 2 is where it primarily moves).
            ds.gapOpen = Math.max(0, Math.round((ds.gapOpen - gapClosed) * 10) / 10);

            // Apply deltas with 0–100 clamps; meters start low and keep headroom so every
            // wrong lever still registers through the final round.
            ds.wellbeing = Math.max(0, Math.min(100, ds.wellbeing + wbDelta));
            ds.performance = Math.max(0, Math.min(100, ds.performance + perfDelta));
            ds.credibility = Math.max(0, Math.min(100, ds.credibility + credDelta));
            ds.team = Math.max(0, Math.min(100, ds.team + teamDelta));

            ds.wellbeingHistory.push(Math.round(ds.wellbeing));
            ds.performanceHistory.push(Math.round(ds.performance));
            ds.teamHistory.push(Math.round(ds.team));

            // The single strongest quit predictor: ending the sprint still in the burnout band.
            if (round === this.ROUNDS.length && ds.wellbeing < this.WELLBEING_FLOOR) ds.burnoutEnding = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: ds.performance is already a metric here, so the gradebook's Ruta 1
            // (domainState.performance.overallScore) is unavailable. Persist the composite to the
            // top-level `score` field, which express_resolveDomainScore reads via Ruta 2.
            ds.score = this._composite(ds);

            return {
                period: state.currentPeriod,
                wellbeing: Math.round(ds.wellbeing),
                wellbeingDelta: Math.round(wbDelta),
                performance: Math.round(ds.performance),
                performanceDelta: Math.round(perfDelta),
                credibility: Math.round(ds.credibility),
                credibilityDelta: Math.round(credDelta),
                team: Math.round(ds.team),
                teamDelta: Math.round(teamDelta),
                gapOpen: ds.gapOpen,
                clientFail: ds.clientFail,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
