                if (card) {
                    card.classList.toggle(`boundarysim-wellbeing-healthy`, Number(v) >= this.WIN_WELLBEING);
                    card.classList.toggle(`boundarysim-wellbeing-burnout`, Number(v) < this.WELLBEING_FLOOR);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`performanceDisplay`, `domainState.performance`, (v) => Math.round(v));
            uiManager.bind(`credibilityDisplay`, `domainState.credibility`, (v) => Math.round(v));
            uiManager.bind(`teamDisplay`, `domainState.team`, (v) => Math.round(v));
            uiManager.bind(`budgetDisplay`, `domainState.gapOpen`, (v) => {
                const bar = document.querySelector(`.boundarysim-budget-bar`);
                if (bar) {
                    bar.classList.toggle(`boundarysim-budget-gap-closed`, Number(v) <= 0.05);
                    bar.classList.toggle(`boundarysim-budget-gap-open`, Number(v) > 0.05);
                }
                return Number(v).toFixed(1) + `h / 20.0h`;
            });

            const self = this;

            // Honesty slider readout.
            const hon = document.getElementById(`honestyInput`);
            const honReadout = document.getElementById(`honestyReadout`);
            if (hon && honReadout) {
                honReadout.textContent = hon.value;
                hon.addEventListener(`input`, function() { honReadout.textContent = hon.value; });
            }

            // Enforce slider readout.
            const enf = document.getElementById(`enforceInput`);
            const enfReadout = document.getElementById(`enforceReadout`);
            if (enf && enfReadout) {
                enfReadout.textContent = enf.value;
                enf.addEventListener(`input`, function() { enfReadout.textContent = enf.value; });
            }

            // Gap-allocation live total (must reach 20.0h).
            const gapIds = [`delegateInput`, `temporalInput`, `physicalInput`, `commInput`];
            const gapReadout = document.getElementById(`gapReadout`);
            const recompute = function() {
                let total = 0;
                gapIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (gapReadout) gapReadout.textContent = total.toFixed(1);
                const bar = document.querySelector(`.boundarysim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.GAP_HOURS) > 0.05) ? `#c0392b` : ``;
            };
            gapIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

