        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.wellbeingHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                boundaryChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.wellbeingHistory },
                        { data: ds.performanceHistory },
                        { data: ds.teamHistory }
                    ]
                }
            };
        }

        // v1.1.0: single source of truth for the composite (verbatim v1.0.0 formula).
        _composite(ds) {
            const wellbeing = Math.round(ds.wellbeing);
            const performance = Math.round(ds.performance);
            const credibility = Math.round(ds.credibility);
            const team = Math.round(ds.team);
            return Math.round(wellbeing * 0.30 + performance * 0.25 + credibility * 0.22 + team * 0.23);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const wellbeing = Math.round(ds.wellbeing);
            const performance = Math.round(ds.performance);
            const credibility = Math.round(ds.credibility);
            const team = Math.round(ds.team);

            const sustainable = wellbeing >= this.WIN_WELLBEING;
            const delivered = performance >= this.WIN_PERFORMANCE;
            const burnout = ds.burnoutEnding || wellbeing < this.WELLBEING_FLOOR;
            const composite = this._composite(ds);

            let performanceLabel = `Quit-Risk Band`, performanceKey = `grade_quitrisk`;
            if (sustainable && delivered && team >= 60 && composite >= 70) { performanceLabel = `Sustained & Reset the Norm`; performanceKey = `grade_sustained`; }
            else if (sustainable && delivered) { performanceLabel = `Held Both, Norm Still Fragile`; performanceKey = `grade_heldboth`; }
            else if (delivered && burnout) { performanceLabel = `Delivered but Burning Out`; performanceKey = `grade_burning`; }
            else if (sustainable && !delivered) { performanceLabel = `Protected Self, Client at Risk`; performanceKey = `grade_protected`; }
            else if (composite >= 45) { performanceLabel = `Mixed — Boundaries Half-Held`; performanceKey = `grade_mixed`; }

            const insights = [];
            if (sustainable && delivered && team >= 60) insights.push(window.mySimulation.t(`insight_sustained`));
            else if (delivered && burnout) insights.push(window.mySimulation.t(`insight_burnout`));
            else if (sustainable && !delivered) insights.push(window.mySimulation.t(`insight_clientrisk`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (burnout) insights.push(window.mySimulation.t(`insight_quitrisk`));
            if (credibility < 45) insights.push(window.mySimulation.t(`insight_lowcred`));
            if (team < 45) insights.push(window.mySimulation.t(`insight_solofix`));
            if (ds.clientFail) insights.push(window.mySimulation.t(`insight_wentdark`));
            if (sustainable && delivered && team >= 60 && credibility >= 60) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                wellbeing: wellbeing,
                performance: performance,
                credibility: credibility,
                team: team,
                sustainable: sustainable,
                delivered: delivered,
                burnout: burnout,
                met: (sustainable && delivered),
                composite: composite,
                overallScore: composite,
                performanceLabel: performanceLabel,
                performanceKey: performanceKey,
                totalPeriods: history.length,
                insights: insights
            };
        }

        // v1.1.0: localized completion debrief (engine otherwise shows a generic fallback).
        formatCompletionMessage(summary) {
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            const s = summary || {};
            const raw = (s.composite != null) ? s.composite : (s.overallScore != null ? s.overallScore : 0);
            const score = Math.max(0, Math.min(100, Math.round(Number(raw) || 0)));
            const grade = s.performanceKey ? t(s.performanceKey) : (s.performanceLabel || '');
            const badge = s.met
                ? `<span class="boundarysim-cm-badge boundarysim-cm-badge-ok">${t('cm_targets_met')}</span>`
                : `<span class="boundarysim-cm-badge boundarysim-cm-badge-miss">${t('cm_targets_missed')}</span>`;
            const kpi = (k, v, suf) => `<div class="boundarysim-cm-kpi"><div class="boundarysim-cm-kpi-val">${(v != null ? v : '—')}${suf || ''}</div><div class="boundarysim-cm-kpi-lbl">${t(k)}</div></div>`;
            const ins = Array.isArray(s.insights) ? s.insights : [];
            const insHtml = ins.length
                ? `<div class="boundarysim-cm-insights"><div class="boundarysim-cm-ins-h">${t('cm_insights')}</div><ul>${ins.map((i) => `<li>${i}</li>`).join('')}</ul></div>`
                : '';
            return `
                <div class="boundarysim-cm">
                    <div class="boundarysim-cm-title">${t('cm_title')}</div>
                    <div class="boundarysim-cm-scorewrap">
                        <div class="boundarysim-cm-score">${score}<span class="boundarysim-cm-score-max">/100</span></div>
                        <div class="boundarysim-cm-grade">${grade}</div>
                        <div class="boundarysim-cm-badges">${badge}</div>
                    </div>
                    <div class="boundarysim-cm-kpis">
                        ${kpi('cm_kpi_wellbeing', s.wellbeing, '')}
                        ${kpi('cm_kpi_performance', s.performance, '')}
                        ${kpi('cm_kpi_credibility', s.credibility, '')}
                        ${kpi('cm_kpi_team', s.team, '')}
                    </div>
                    ${insHtml}
                </div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.burnoutEnding) return window.mySimulation.t(`hint_burnout`);
            if (ds.credibility < 30 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_credibility`);
            if (ds.wellbeing < 30) return window.mySimulation.t(`hint_wellbeing`);
            if (state.currentPeriod >= 3 && ds.team < 35) return window.mySimulation.t(`hint_team`);
            if (ds.wellbeing >= this.WIN_WELLBEING && ds.performance >= this.WIN_PERFORMANCE && ds.team >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

