                    warn_honesty_range:     `La franqueza de Priya debe ser un porcentaje entre 0 y 100.`,
                    warn_alloc_negative:    `Las horas asignadas a una familia de tácticas no pueden ser negativas.`,
                    warn_alloc_total:       `Tu plan debe cerrar exactamente 20,0 horas — la brecha es fija. Reequilibra las familias.`,
                    warn_enforce_range:     `El nivel de cumplimiento debe ser un porcentaje entre 0 y 100.`,
